(() => {
 const live=document.querySelector('#live-media'),replays=document.querySelector('#replay-media');if(!live||!replays)return;
 const lang=document.documentElement.lang==='en'?'en':'fr',api='https://twjpjzalyvbsdpbzhqln.supabase.co/functions/v1/public-event';
 const empty=lang==='fr'?'Aucun lien publié pour le moment.':'No link published yet.';
 const youtubeId=value=>{try{const url=new URL(value),host=url.hostname.toLowerCase().replace(/^www\./,'');if(url.protocol!=='https:')return null;const id=host==='youtu.be'?url.pathname.split('/')[1]:host==='youtube.com'?(url.pathname==='/watch'?url.searchParams.get('v'):url.pathname.match(/^\/(?:shorts|embed|live)\/([^/]+)/)?.[1]):null;return /^[a-zA-Z0-9_-]{11}$/.test(id||'')?id:null;}catch{return null;}};
 const card=item=>{const article=document.createElement('article');article.className='media-card';const type=document.createElement('span');type.className='meta';type.textContent=item.media_type==='live'?'LIVE':'REPLAY';const title=document.createElement('h3');title.textContent=item['title_'+lang]||item.title_fr;const link=document.createElement('a');link.className='action';link.href=item.url;link.target='_blank';link.rel='noopener noreferrer';link.textContent=(item.media_type==='live'?(lang==='fr'?'Voir le direct':'Watch live'):(lang==='fr'?'Voir sur YouTube':'Watch on YouTube'))+' ↗';const id=youtubeId(item.url);if(id){article.classList.add('media-video-card');const preview=document.createElement('a');preview.className='media-preview';preview.href=item.url;preview.target='_blank';preview.rel='noopener noreferrer';preview.setAttribute('aria-label',(lang==='fr'?'Lire : ':'Play: ')+title.textContent);const image=document.createElement('img');image.alt='';image.loading='lazy';image.decoding='async';image.width=1280;image.height=720;image.referrerPolicy='no-referrer';image.src='https://i.ytimg.com/vi/'+id+'/maxresdefault.jpg';let fallback=false;image.onerror=()=>{if(!fallback){fallback=true;image.src='https://i.ytimg.com/vi/'+id+'/hqdefault.jpg';}else image.remove();};const play=document.createElement('span');play.className='media-play';play.textContent='▶';play.setAttribute('aria-hidden','true');preview.append(image,play);article.append(preview);}const copy=document.createElement('div');copy.className='media-copy';copy.append(type,title,link);article.append(copy);return article;};
 (window.ATX_PUBLIC_EVENTS?window.ATX_PUBLIC_EVENTS():fetch(api,{signal:AbortSignal.timeout(12000)}).then(response=>{if(!response.ok)throw Error();return response.json();})).then(data=>{const items=data.media||[],streams=items.filter(x=>x.media_type==='live'),videos=items.filter(x=>x.media_type==='replay');live.replaceChildren(streams[0]?card(streams[0]):Object.assign(document.createElement('p'),{textContent:empty}));replays.replaceChildren(...(videos.length?videos.map(card):[Object.assign(document.createElement('p'),{textContent:empty})]));}).catch(()=>{live.textContent=replays.textContent=lang==='fr'?'Médias momentanément indisponibles.':'Media temporarily unavailable.';});
})();
